    25→        private static FrozenDictionary<UInt256, byte[]> CreateLookup()
    26→        {
    27→            Span<byte> buffer = stackalloc byte[32];
    28→            Dictionary<UInt256, byte[]> lookup = new Dictionary<UInt256, byte[]>(LookupSize);
    29→            for (int i = 0; i < LookupSize; i++)
    30→            {
