   185→        byte[] buffer = new byte[tracer.ReturnValue.Length + 1];
   186→        buffer[0] = (byte)type;
   187→        tracer.ReturnValue.AsSpan().CopyTo(buffer.AsSpan(1));
   188→        requests.Add(buffer);
   189→    }
